              setActive(0);
            }}
          />
        </Column>

        <VisuallyHidden>
          <span role="status" aria-live="polite">
            {flat.length === 0
              ? "No results"
              : `${flat.length} results. ${activeCommand ? `${activeCommand.label}, ${activeCommand.group}, highlighted.` : ""}`}
          </span>
        </VisuallyHidden>

        <div
          id={listId}
          role="listbox"
          aria-label="Results"
          style={{ maxHeight: "22rem", overflowY: "auto", padding: "0 0.5rem 0.5rem" }}
        >
          {flat.length === 0 ? (
