                <Text textVariant="label-strong-s">{row.name}</Text>
                <Text textVariant="body-default-xs" onBackground="neutral-weak">
                  {row.email}
                </Text>
              </Column>
            </Row>
          ),
        },
        { key: "role", header: "Role", sortable: true, sort: (a, b) => a.role.localeCompare(b.role) },
